window.RP_SESSION={"id":"S-b65749a7cb47","messages":[{"id":"RP-II-0114305","time":"2026-07-05T18:42:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"오늘 캐리해서 뿌듯한 레마 캐롤라인 입니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114306","time":"2026-07-05T18:43:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114307","time":"2026-07-05T18:43:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 지능 판정 :\n[2] + [1] = [3]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-II-0114308","time":"2026-07-05T18:43:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114309","time":"2026-07-05T18:43:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"와 이거 세션에서 떴으면 변수였다","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114310","time":"2026-07-05T18:43:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114311","time":"2026-07-05T18:43:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 민첩 판정 :\n[1] + [2] = [3]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-II-0114312","time":"2026-07-05T18:43:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"뭐?","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114313","time":"2026-07-05T18:43:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"오늘 낮에 무리했더니 몸에 피곤이 쌓여서 훈련을 못 하겠다고 생각한 레마는","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114314","time":"2026-07-05T18:49:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"모닥불 터 옆에 드러누워서 쉬고 있다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114315","time":"2026-07-05T18:52:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"흠...","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114316","time":"2026-07-05T18:52:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"이제 뭐 하지?","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114317","time":"2026-07-05T18:52:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"이야, 뭘 이래 가져왔대?\"","characters":["P-55e987e3c831"]},{"id":"RP-II-0114318","time":"2026-07-05T18:53:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"길드에 도착한 수레에서 내린 짐을 들고 모닥불을 지나칩니다.","characters":["P-55e987e3c831"]},{"id":"RP-II-0114319","time":"2026-07-05T18:53:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"뭔 숯도 좀 있는 거 같고. 쓸만하겠는데?\"","characters":["P-55e987e3c831"]},{"id":"RP-II-0114320","time":"2026-07-05T18:54:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"다른 갑옷이랑 무기도 그렇지만 숯 자체도 상당히 깔끔하게 탔네. 뭐지? 그냥 탄 건 아닌데.\"","characters":["P-55e987e3c831"]},{"id":"RP-II-0114321","time":"2026-07-05T18:54:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 저, 저도 뭔지는 잘 모, 몰라요. 기절해서 그 수레에 시, 싣겨온 입장이라... 그래도 미, 민폐는 안 끼쳤으니 거, 걱정 마요! \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114322","time":"2026-07-05T18:54:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"그래, 그래. 고생했어. 흐흐.\"","characters":["P-55e987e3c831"]},{"id":"RP-II-0114323","time":"2026-07-05T18:55:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그 길로 레마를 지나쳐서 대장간으로 들어가죠. 창고에 잘 놔두고, 수레와 몇번 왕복할 겁니다.","characters":["P-55e987e3c831"]},{"id":"RP-II-0114324","time":"2026-07-05T18:55:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"브랜을 돕고 싶은데...","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114325","time":"2026-07-05T18:55:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114326","time":"2026-07-05T18:55:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 힘 판정 :\n[4] + [1] = [5]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0114327","time":"2026-07-05T18:55:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"임무에서 기절했다 깨어나서 잠시간 몸에 힘이 없다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114328","time":"2026-07-05T18:55:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 헤헤... \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114329","time":"2026-07-05T18:56:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"한번 대장간을 들어갔다가 나오는 브랜이 그걸 볼 겁니다.","characters":["P-55e987e3c831"]},{"id":"RP-II-0114330","time":"2026-07-05T18:56:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"수레쪽으로 가며 말해요. \"너무 힘 쓰지 마. 오늘 많은 일이 있었던 거 같던데.\"","characters":["P-55e987e3c831"]},{"id":"RP-II-0114331","time":"2026-07-05T18:57:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 정말... 마, 많은 일이 있었죠! \"\n\n옆에 앉아서 브랜이 일하는걸 지켜본다.\n\n\" 브랜 씨, 마음에 드, 드시는 전리품 있나요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114332","time":"2026-07-05T18:57:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"음... 이 갑옷이 제일인가 역시...\"","characters":["P-55e987e3c831"]},{"id":"RP-II-0114333","time":"2026-07-05T18:58:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"내가 입을 건 아니지만, 상당히 깔끔하게 보존됐어. 가슴팍에 구멍 몇개는 보이지만 이 정도는 그냥 철편을 바꾸면 되고...\"","characters":["P-55e987e3c831"]},{"id":"RP-II-0114334","time":"2026-07-05T18:58:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"이런 것도 나름 고가품이란 말이지.\"","characters":["P-55e987e3c831"]},{"id":"RP-II-0114335","time":"2026-07-05T18:59:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그렇게 브리건딘 코트를 가르키더니 그걸 어깨에 들쳐매네요.","characters":["P-55e987e3c831"]},{"id":"RP-II-0114336","time":"2026-07-05T18:59:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"그리고 숯은 잘 모르겠는데, 다음에 써보려고. 뭐 저런 큰 숯이 있담.\"","characters":["P-55e987e3c831"]},{"id":"RP-II-0114337","time":"2026-07-05T19:00:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"숯을 토막내서 마대자루에 담고, 어깨에 갑옷과 같이 짊어지고 대장간으로 저벅저벅 걸어갑니다.","characters":["P-55e987e3c831"]},{"id":"RP-II-0114338","time":"2026-07-05T19:03:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 언젠가 써 보, 볼게요! \"\n\n브랜이 숯을 토막내는걸 구경하며.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114339","time":"2026-07-05T19:03:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"으응? 뭘 써본다고? 이 숯을? 아니면 다른 거?\"","characters":["P-55e987e3c831"]},{"id":"RP-II-0114340","time":"2026-07-05T19:08:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 숯이요. 제가 요리를 좀 하, 하잖아요. 저걸 가지고 뭔가 구, 구워 보고 싶은데... \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114341","time":"2026-07-05T19:09:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"하지만... 숯은... 나무로 만드는걸... 음... 근데 훈제를 생각해보면 비슷한가? 그래도 역시 좀 아닌 거 같은데...\"","characters":["P-55e987e3c831"]},{"id":"RP-II-0114342","time":"2026-07-05T19:09:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"아, 만드는 게 아니라 써본다고. 아하. 그런 말이였구나. 그거 좋지.\"","characters":["P-55e987e3c831"]},{"id":"RP-II-0114343","time":"2026-07-05T19:09:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"여기 반 남겨두고 갈게. 그 정도면 되려나?\"","characters":["P-55e987e3c831"]},{"id":"RP-II-0114344","time":"2026-07-05T19:12:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 조, 좋아요. 좀 있다가 주, 주방으로 오시면... \"\n\n잠시 고민하다가.\n\n\" 고, 고기랑, 채소랑 버, 버섯 가지고 모듬구이 해 드, 드릴게요. 맛있겠죠! \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114345","time":"2026-07-05T19:13:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"그거 좋네. 흐흐, 기대할게.\"","characters":["P-55e987e3c831"]},{"id":"RP-II-0114346","time":"2026-07-05T19:13:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"그럼 난 마저 정리하고 갈테니까. 있다 보자고.\"","characters":["P-55e987e3c831"]},{"id":"RP-II-0114347","time":"2026-07-05T19:14:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 조, 좋아요! \"\n\n레마는 일어나서 주머니를 확인하고 고기를 좀 사러 도시로 가기 시작한다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114348","time":"2026-07-05T19:14:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"브랜도 마저 대장간으로 향하죠잇","characters":["P-55e987e3c831"]},{"id":"RP-II-0114349","time":"2026-07-05T19:14:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-fec1db60d51e"]},{"id":"RP-II-0114350","time":"2026-07-05T19:14:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
